  checkL:"El control nocturno espera",checks:[["empty","Que no esté vacía"],["range","De 2,000 a 5,000 filas"],["weekday","Las filas de ese día"],["campus","Cada sede, ese día"]],
  mondayB:"Lunes en la noche: llegan 2,030 filas",monL:"Las inscripciones del lunes en la noche",campus:[["Norte",1030,1010],["Sur",1020,1020],["Centro",2050,0]],
